<script setup lang="ts">
import type { CodeEnvelope } from '~/types/api'
definePageMeta({middleware:'auth'});useSeoMeta({title:'生涯报告'})
const api=useApi();const auth=useAuth();const toast=useToast();const resumes=ref<any[]>([]);const resumeId=ref<number>();const query=ref('');const searching=ref(false);const candidates=ref<any[]>([]);const targets=ref<any[]>([]);const goal=ref('fit');const loading=ref('');const reportId=ref<number>();const report=ref<any>();const history=ref<any[]>([]);const historyOpen=ref(false);const reviewText=ref('');const cacheKey=computed(()=>`career_report_workspace_v1_${auth.user.value?.id||'guest'}`)
function persist(){if(import.meta.client)localStorage.setItem(cacheKey.value,JSON.stringify({v:1,userId:auth.user.value?.id||'guest',savedAt:Date.now(),resumeId:resumeId.value,targets:targets.value,goal:goal.value,reportId:reportId.value,report:report.value}))}
async function search(){searching.value=true;try{const data=await api.ok<any>('/api/report/targets/manual-search',{method:'POST',body:{q:query.value,limit:20}});candidates.value=data.targets||[]}catch(e){toast.add({title:String(e),color:'error'})}finally{searching.value=false}}
function addTarget(item:any){if(targets.value.length>=5){toast.add({title:'最多选择 5 个目标',color:'warning'});return};if(!targets.value.some(x=>x.job_id===item.job_id))targets.value.push(item);persist()}
function removeTarget(index:number){targets.value.splice(index,1);persist()}
async function generate(){if(!resumeId.value||!targets.value.length){toast.add({title:'请选择画像和目标岗位',color:'warning'});return};loading.value='generate';try{const data=await api.ok<any>('/api/report/generate',{method:'POST',body:{resume_id:resumeId.value,target_job_ids:targets.value.map(x=>x.job_id),primary_job_id:targets.value[0].job_id,match_goal:goal.value,skip_llm_enrich:true}});reportId.value=data.report_id;report.value=data.report;persist();if(data.llm_enrich_pending!==false){loading.value='enrich';const enriched=await api.ok<any>(`/api/report/${data.report_id}/enrich`,{method:'POST',body:{}});report.value=enriched.report||report.value;persist()}toast.add({title:'报告生成成功',color:'success'})}catch(e){toast.add({title:String(e),color:'error'})}finally{loading.value=''}}
async function openHistory(){historyOpen.value=true;try{history.value=(await api.ok<{items:any[]}>('/api/report/my/list?limit=30')).items}catch(e){toast.add({title:String(e),color:'error'})}}
async function restore(id:number){const data=await api.ok<any>(`/api/report/${id}`);reportId.value=data.report_id;report.value=data.report;historyOpen.value=false;persist()}
async function review(){if(!reportId.value||!reviewText.value.trim())return;loading.value='review';try{await api.ok('/api/report/review-cycle',{method:'POST',body:{report_id:reportId.value,review_text:reviewText.value}});const latest=await api.ok<any>(`/api/report/${reportId.value}`);report.value=latest.report;reviewText.value='';persist();toast.add({title:'复盘已提交',color:'success'})}catch(e){toast.add({title:String(e),color:'error'})}finally{loading.value=''}}
async function exportPdf(){if(!reportId.value)return;loading.value='pdf';try{const response=await api.request<Blob>(`/api/report/${reportId.value}/export/pdf`,{responseType:'blob'});const url=URL.createObjectURL(response);const a=document.createElement('a');a.href=url;a.download=`career_report_${reportId.value}.pdf`;a.click();URL.revokeObjectURL(url)}catch(e){toast.add({title:String(e),color:'error'})}finally{loading.value=''}}
onMounted(async()=>{auth.hydrate();const body=await api.request<CodeEnvelope<any[]>>('/api/profile/resumes');if(body.code===200)resumes.value=body.data||[];const raw=localStorage.getItem(cacheKey.value);if(raw)try{const c=JSON.parse(raw);resumeId.value=c.resumeId;targets.value=c.targets||[];goal.value=c.goal||'fit';reportId.value=c.reportId;report.value=c.report}catch{}})
watch([resumeId,targets,goal],persist,{deep:true})
</script>
<template><div class="page-stack"><div class="flex flex-wrap items-end justify-between gap-3"><div class="page-heading"><h1>职业生涯发展报告</h1><p class="muted">选择目标、生成成长计划，并按月复盘调整</p></div><UButton icon="i-lucide-history" variant="soft" @click="openHistory">历史报告</UButton></div><UCard><div class="grid gap-4 lg:grid-cols-3"><UFormField label="能力画像"><USelect v-model="resumeId" :items="resumes.map(x=>({label:`${x.name} · ${x.major}`,value:x.id}))" class="w-full"/></UFormField><UFormField label="目标模式"><USelect v-model="goal" :items="[{label:'稳妥目标',value:'fit'},{label:'冲刺目标',value:'stretch'}]"/></UFormField><UFormField label="搜索目标岗位"><div class="flex gap-2"><UInput v-model="query" class="flex-1" @keyup.enter="search"/><UButton :loading="searching" @click="search">搜索</UButton></div></UFormField></div><div v-if="candidates.length" class="mt-4 flex flex-wrap gap-2"><UButton v-for="x in candidates" :key="x.job_id" size="sm" color="neutral" variant="soft" @click="addTarget(x)">{{x.title}} · {{x.company}}</UButton></div><div class="mt-4 flex flex-wrap gap-2"><UBadge v-for="(x,i) in targets" :key="x.job_id" :label="x.title||x.job_id" class="cursor-pointer" @click="removeTarget(Number(i))"/><span v-if="!targets.length" class="text-sm muted">尚未选择目标（最多 5 个）</span></div><UButton class="mt-5" size="lg" :loading="loading==='generate'||loading==='enrich'" @click="generate">{{loading==='enrich'?'AI 增强中…':'生成报告'}}</UButton></UCard><UEmpty v-if="!report" title="尚未生成报告" description="选择画像和至少一个目标岗位"/><template v-else><div class="flex flex-wrap gap-2"><UButton :loading="loading==='pdf'" icon="i-lucide-download" variant="soft" @click="exportPdf">导出 PDF</UButton><UBadge :label="`报告 #${reportId}`"/></div><UCard><template #header><h2 class="text-xl font-semibold">报告摘要</h2></template><p class="whitespace-pre-wrap">{{report.summary||report.overview||report.narrative||'报告已生成，请查看各模块。'}}</p></UCard><UTabs :items="[{label:'目标与差距',slot:'targets'},{label:'成长计划',slot:'plans'},{label:'资源与竞赛',slot:'resources'},{label:'完整数据',slot:'raw'}]" class="w-full"><template #targets><UCard><pre class="overflow-auto whitespace-pre-wrap text-sm">{{JSON.stringify({targets:report.targets,target_insights:report.target_insights,gap_analysis:report.gap_analysis},null,2)}}</pre></UCard></template><template #plans><ReportPlanView :report-id="reportId!" :plans="report.plans_by_target||[]" @changed="persist"/></template><template #resources><UCard><pre class="overflow-auto whitespace-pre-wrap text-sm">{{JSON.stringify(report.recommendations||report.resources||{},null,2)}}</pre></UCard></template><template #raw><UCard><pre class="overflow-auto whitespace-pre-wrap text-xs">{{JSON.stringify(report,null,2)}}</pre></UCard></template></UTabs><UCard><template #header><h2 class="text-lg font-semibold">本月复盘</h2></template><UTextarea v-model="reviewText" :rows="7" placeholder="记录本月完成情况、困难、作品或数据变化…" class="w-full"/><UButton class="mt-3" :loading="loading==='review'" @click="review">提交复盘并更新计划</UButton></UCard></template><UModal v-model:open="historyOpen" title="历史报告"><template #body><div class="grid gap-2"><UButton v-for="x in history" :key="x.report_id" color="neutral" variant="soft" block @click="restore(x.report_id)">{{x.title}} · {{x.created_at}}</UButton><UEmpty v-if="!history.length" title="暂无历史报告"/></div></template></UModal></div></template>
